module.exports = function (RED) {
  "use strict";

  function EntityNode(n) {
    RED.nodes.createNode(this, n);
    /* Handle legacy */

    console.log("ENTITY NODE: ", n);

    if (!Array.isArray(n.props)) {
      n.props = [];
      n.props.push({
        p: "payload",
        v: n.payload,
        vt: n.payloadType,
      });
    } else {
      for (var i = 0, l = n.props.length; i < l; i++) {
        var item = n.props[i];
        if (item.p === "payload" && !item.hasOwnProperty("v")) {
          item.v = n.payload;
          item.vt = n.payloadType;
        } else if (
          item.p === "topic" &&
          item.vt === "str" &&
          !item.hasOwnProperty("v")
        ) {
          item.v = n.topic;
        }
      }
    }
    this.props = n.props;
    console.log(this.props);
    this.subject = n.name;
    var node = this;

    node.props.forEach(function (prop) {
      if (prop.vt === "jsonata") {
        try {
          var val = prop.v ? prop.v : "";
          prop.exp = RED.util.prepareJSONataExpression(val, node);
        } catch (err) {
          node.error(
            RED._("entity.errors.invalid-expr", { error: err.message })
          );
          prop.exp = null;
        }
      }
    });

    this.on("input", function (msg, send, done) {
      var errors = [];

      this.props.forEach((p) => {
        var property = p.p;
        var value = p.v ? p.v : "";
        var valueType = p.vt ? p.vt : "str";
        console.log("ENTITY property: ", property, " ", value, " ", valueType);

        if (!property) return;

        if (valueType === "jsonata") {
          if (p.exp) {
            try {
              var val = RED.util.evaluateJSONataExpression(p.exp, msg);
              RED.util.setMessageProperty(msg, property, val, true);
            } catch (err) {
              errors.push(err.message);
            }
          }
          return;
        }
        try {
          RED.util.setMessageProperty(
            msg,
            property,
            RED.util.evaluateNodeProperty(value, valueType, this, msg),
            true
          );
        } catch (err) {
          errors.push(err.toString());
        }
      });

      if (errors.length) {
        done(errors.join("; "));
      } else {
        msg.attributes = n.props;
        send(msg);
        done();
      }
    });
  }

  RED.nodes.registerType("entity", EntityNode);
  RED.httpAdmin.post(
    "/entity/:id",
    RED.auth.needsPermission("entity.write"),
    function (req, res) {
      var node = RED.nodes.getNode(req.params.id);
      if (node != null) {
        try {
          node.receive();
          res.sendStatus(200);
        } catch (err) {
          res.sendStatus(500);
          node.error(RED._("entity.failed", { error: err.toString() }));
        }
      } else {
        res.sendStatus(404);
      }
    }
  );
};
